    sources = [obj for obj in objs if obj not in frames]
    if not sources:
        return out
    src = max(sources, key=lambda obj: len(obj[5]))
    _, r0, r1, c0, c1, cells = src
    sh, sw = r1-r0+1, c1-c0+1
    pattern = [[grid[r0+i][c0+j] != 0 for j in range(sw)] for i in range(sh)]

    for color, a, b, c, d, _ in frames:
        ih, iw = b-a-1, d-c-1
        if ih <= 0 or iw <= 0:
            continue
        # Only fill initially empty frame interiors.
        if any(grid[r][x] != 0 for r in range(a+1, b) for x in range(c+1, d)):
            continue
        for i in range(ih):
            for j in range(iw):
                si = min(sh-1, i*sh//ih)
                sj = min(sw-1, j*sw//iw)
                if pattern[si][sj]:
