def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objs = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            objs.append((color, min(rs), max(rs), min(cs), max(cs), cells))

    frames = []
    patterned = []
    for obj in objs:
        color, r0, r1, c0, c1, cells = obj
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        boundary = all(grid[r][c] == color
                       for r in range(r0, r1+1)
                       for c in range(c0, c1+1)
                       if r in (r0, r1) or c in (c0, c1))
        if not boundary:
            continue
        interior = [[grid[r][c] == color for c in range(c0+1, c1)]
                    for r in range(r0+1, r1)]
        if any(v for row in interior for v in row):
            patterned.append((obj, interior))
        else:
            frames.append(obj)

    if patterned:
        # The patterned rectangle is the source motif; its border is not part
        # of the motif, only its interior pattern is copied.
        source_obj, pattern = max(patterned, key=lambda z: len(z[1]) * len(z[1][0]))
        ph, pw = len(pattern), len(pattern[0])
        for color, r0, r1, c0, c1, cells in frames:
            ih, iw = r1-r0-1, c1-c0-1
            for i in range(ih):
                for j in range(iw):
                    si = min(ph-1, i*ph//ih)
                    sj = min(pw-1, j*pw//iw)
                    if pattern[si][sj]:
                        out[r0+1+i][c0+1+j] = color

        # A patterned object that is not itself a complete target frame is
        # removed after its pattern has been transferred.
        _, a, b, c, d, cells = source_obj
        for r, col in cells:
            out[r][col] = 0

    return out
